"""Desk API of the page "Poste MCF" (browser station, Chrome/Edge + Web Serial).

These calls use the cashier's normal ERPNext session (CSRF-protected). They never carry the
device signature; conversely the gateway calls (gateway.api) never carry the session:
  * enroll_station  - sends the public key generated by WebCrypto (non-extractable private key);
  * open_session    - gives a short-lived operator token (12 h) bound to THIS station and THIS user;
                      the page adds it to its signed gateway calls (header X-DGI-Operator);
  * close_session   - revokes the token (page closed, user logs out of the station).
Only users with the role DGI Caisse MCF (or DGI Fiscal Manager / System Manager) can operate a
station, and only for points de vente they can read.
"""
import time

import frappe
from frappe import _
from frappe.rate_limiter import rate_limit

from dgi_compliance.gateway.auth import (KIND_BROWSER, OPERATOR_TOKEN_TTL_S, issue_operator_token,
                                         revoke_operator_token, user_may_operate)
from dgi_compliance.gateway.events import log_event


def _require_operator():
    if not user_may_operate(frappe.session.user):
        frappe.throw(_("Le role DGI Caisse MCF est requis pour utiliser un poste MCF."), frappe.PermissionError)


def _station(gateway_id):
    gateway_id = (gateway_id or "").strip().upper()
    if not gateway_id or not frappe.db.exists("DGI Gateway", gateway_id):
        frappe.throw(_("Poste MCF inconnu."), frappe.DoesNotExistError)
    gw = frappe.get_doc("DGI Gateway", gateway_id)
    if gw.get("kind") != KIND_BROWSER:
        frappe.throw(_("{0} n'est pas un poste navigateur.").format(gw.name))
    if not frappe.has_permission("DGI Point of Sale", "read", gw.point_of_sale):
        frappe.throw(_("Vous n'avez pas acces au point de vente {0}.").format(gw.point_of_sale), frappe.PermissionError)
    return gw


@frappe.whitelist()
def stations() -> list:
    _require_operator()
    out = []
    for r in frappe.get_all("DGI Gateway", filters={"kind": KIND_BROWSER, "status": ["!=", "Revoquee"]},
                            fields=["name", "point_of_sale", "mcf_device", "status", "key_fingerprint", "last_seen",
                                    "baudrate"],
                            order_by="name asc"):
        if frappe.has_permission("DGI Point of Sale", "read", r.point_of_sale):
            out.append(r)
    return out


@frappe.whitelist(methods=["POST"])
@rate_limit(limit=10, seconds=3600)
def enroll_station(gateway_id=None, code=None, public_key=None, device=None, host=None) -> dict:
    _require_operator()
    gw = _station(gateway_id)
    from dgi_compliance.dgi_compliance.doctype.dgi_gateway.dgi_gateway import enroll_gateway
    device = frappe.parse_json(device) if isinstance(device, str) else (device or {})
    host = frappe.parse_json(host) if isinstance(host, str) else (host or {})
    host = dict(host, operator=frappe.session.user)
    res = enroll_gateway(gw.name, code, public_key, device, host, enrolled_by=frappe.session.user)
    frappe.db.commit()
    return res


@frappe.whitelist(methods=["POST"])
def open_session(gateway_id=None) -> dict:
    _require_operator()
    gw = _station(gateway_id)
    if gw.status != "Active":
        return {"status": gw.status, "fingerprint": gw.key_fingerprint}
    token = issue_operator_token(gw.name, frappe.session.user)
    log_event(gw.name, "POSTE_OUVERT", _("Poste MCF ouvert par {0}.").format(frappe.session.user),
              details={"ip": getattr(frappe.local, "request_ip", None)})
    from dgi_compliance.dgi_compliance.doctype.dgi_gateway.dgi_gateway import gateway_config
    return {"status": gw.status, "operator_token": token, "ttl_s": OPERATOR_TOKEN_TTL_S,
            "server_epoch": int(time.time()), "config": gateway_config(gw), "fingerprint": gw.key_fingerprint}


@frappe.whitelist(methods=["POST"])
def close_session(gateway_id=None, operator_token=None) -> dict:
    gw = _station(gateway_id)
    revoke_operator_token(gw.name, operator_token)
    return {"ok": True}


@frappe.whitelist(methods=["POST"])
@rate_limit(limit=20, seconds=3600)
def propose_device(gateway_id=None, observation=None) -> dict:
    """'Proposer ce MCF' (livrable B section 7, step 3): values read in the MCF on this cash desk, without
    fiscal effect (C1h, 2Bh, C2h). Creates / completes a 'Detecte' MCF; never activates it."""
    from dgi_compliance.fiscal import mcf_format as F
    from dgi_compliance.fiscal.registry import record_observation
    _require_operator()
    gw = _station(gateway_id)
    observation = frappe.parse_json(observation) if isinstance(observation, str) else (observation or {})
    nid = F.nid_of(str(observation.get("mid") or ""))
    other = frappe.db.get_value("DGI Point of Sale", {"mcf_device": nid, "is_active": 1,
                                                      "name": ["!=", gw.point_of_sale]}) if nid else None
    if other and frappe.db.get_value("DGI MCF Device", nid, "status") == "Actif":
        log_event(gw.name, "MCF_REFUSE", _("MCF {0} propose pour {1} alors qu'il est actif sur {2}.")
                  .format(nid, gw.point_of_sale, other), level="Alerte")
        frappe.db.commit()
        frappe.throw(_("Ce MCF (NID {0}) est deja actif sur un autre point de vente.").format(nid))
    observation["proposed_for"] = gw.point_of_sale
    res = record_observation(observation, frappe.session.user, gateway=gw.name)
    frappe.db.commit()
    return res


@frappe.whitelist(methods=["POST"])
def connectivity_test(gateway_id=None, result=None) -> dict:
    """'Tester la connexion' (no fiscal effect): result of C1h + C2h read by the page."""
    from dgi_compliance.fiscal.registry import record_connectivity
    _require_operator()
    gw = _station(gateway_id)
    result = frappe.parse_json(result) if isinstance(result, str) else (result or {})
    if not gw.mcf_device:
        frappe.throw(_("Aucun MCF rattache a ce poste."))
    out = record_connectivity(gw.mcf_device, result, gw.name, frappe.session.user)
    frappe.db.commit()
    return out
